    moves.sort()

    def bfs(start):
        INF = 10**9
        dist = [[INF] * h for _ in range(w)]
        if start in blocked:
            return dist
        from collections import deque
        q = deque([start])
        dist[start[0]][start[1]] = 0
        while q:
